#!/usr/bin/env node
// Prototype driver. Keys live as JSON files in --dir (default ./.tenuo-review),
// one per agent plus the instance's issuer key. In Commonly proper, an agent's
// key is generated by its seat and never leaves it, and the issuer key lives in
// the backend's secret store.
//
//   tenuo-review init-instance
//   tenuo-review keygen <agent>
//   tenuo-review issue --author <agent> --reviewers <a,b> --repo <owner/name>
//   tenuo-review request --author <agent> --repo <r> --pr <n> --sha <sha>   > request.json
//   tenuo-review approve --reviewer <agent> --request request.json --repo <r> --pr <n> --sha <sha>
//   tenuo-review verify-merge --author <agent> --repo <r> --pr <n> --sha <sha> --approvals a,b
//   tenuo-review request-merge --author <agent> --repo <r> --pr <n> --sha <sha> --approvals a,b --verifier <url>
import { mkdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { parseArgs } from "node:util";
import {
  generateAgentKey, generateIssuerKey, issueMergeWarrant, requestApproval, signApproval, verifyMerge, presentMerge,
  warrantComment, approvalComment, inspectApproval,
} from "../src/index.js";

const { values: o, positionals: [cmd, name] } = parseArgs({
  allowPositionals: true,
  options: {
    dir: { type: "string", default: ".tenuo-review" }, author: { type: "string" }, reviewer: { type: "string" },
    reviewers: { type: "string" }, repo: { type: "string" }, pr: { type: "string" }, sha: { type: "string" },
    request: { type: "string" }, approvals: { type: "string" }, ttl: { type: "string" }, verifier: { type: "string" },
  },
});
mkdirSync(o.dir, { recursive: true, mode: 0o700 });
const file = (n) => join(o.dir, `${n}.json`);
const load = (n) => { if (!existsSync(file(n))) throw new Error(`no ${n} in ${o.dir}`); return JSON.parse(readFileSync(file(n), "utf8")); };
const save = (n, v) => writeFileSync(file(n), JSON.stringify(v, null, 1), { mode: 0o600 });
const instance = () => load("instance");
const readApprovals = (list) => (list ?? "").split(",").filter(Boolean).map((p) => {
  const t = readFileSync(p, "utf8"); const m = t.match(/"approval":"([^"]+)"/); return m ? m[1] : t.trim();
});

switch (cmd) {
  case "init-instance": {
    if (existsSync(file("instance"))) throw new Error("instance key exists");
    const k = generateIssuerKey(); save("instance", k);
    console.log(JSON.stringify({ trusted_roots: [k.publicHex] }, null, 2));
    break;
  }
  case "keygen": {
    if (!name) throw new Error("keygen <agent>");
    if (existsSync(file(name))) throw new Error(`${name} exists`);
    const k = generateAgentKey(); save(name, { name, ...k });
    console.log(k.publicHex);
    break;
  }
  case "issue": {
    const author = load(o.author);
    const reviewers = o.reviewers.split(",").map((r) => load(r).publicHex);
    const warrant = issueMergeWarrant({ issuerSecretHex: instance().secretHex, authorPublicHex: author.publicHex, reviewerPublicHex: reviewers, repo: o.repo, ttlSeconds: Number(o.ttl ?? 3600) });
    save(`${o.author}.warrant`, { warrant, repo: o.repo });
    console.log(warrantComment({ warrant, agent: o.author }));
    break;
  }
  case "request": {
    const author = load(o.author);
    const { warrant } = load(`${o.author}.warrant`);
    const req = requestApproval({ trustedRootHex: instance().publicHex, warrant, authorSecretHex: author.secretHex, repo: o.repo, pr: o.pr, headSha: o.sha });
    console.log(JSON.stringify(req, null, 1));
    break;
  }
  case "approve": {
    const reviewer = load(o.reviewer);
    const request = JSON.parse(readFileSync(o.request, "utf8"));
    const approval = signApproval({ request, reviewerSecretHex: reviewer.secretHex, reviewerName: o.reviewer, expect: { repo: o.repo, pr: o.pr, headSha: o.sha } });
    console.error(JSON.stringify(inspectApproval(approval)));
    console.log(approvalComment({ approval, reviewer: o.reviewer, headSha: o.sha }));
    break;
  }
  case "request-merge": {
    const author = load(o.author);
    const { warrant } = load(`${o.author}.warrant`);
    const presented = presentMerge({ trustedRootHex: instance().publicHex, warrant, authorSecretHex: author.secretHex, repo: o.repo, pr: o.pr, headSha: o.sha, approvals: readApprovals(o.approvals) });
    const res = await fetch(new URL("/merge-requests", o.verifier), {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ repo: o.repo, pr: Number(o.pr), headSha: o.sha, presented }),
    });
    console.log(res.status, await res.text());
    if (!res.ok) process.exitCode = 1;
    break;
  }
  case "verify-merge": {
    const author = load(o.author);
    const { warrant } = load(`${o.author}.warrant`);
    const approvals = readApprovals(o.approvals);
    try {
      await verifyMerge({ trustedRootHex: instance().publicHex, warrant, authorSecretHex: author.secretHex, repo: o.repo, pr: o.pr, headSha: o.sha, approvals });
      console.log("ALLOW");
    } catch (e) { console.log("DENY", e.code ?? e.message); process.exitCode = 1; }
    break;
  }
  default:
    console.error("usage: see header of bin/tenuo-review.js"); process.exitCode = 2;
}
